import random,re
from eywa.pattern import Pattern
random.seed(7)
literals='abc-.]*\\|()[]'
def enc_lit(c):
 if c in '()[]|*\\': return '\\'+c
 return c
def enc_class_lit(c):
 if c in '-]\\': return '\\'+c
 return c
def gen(depth=0):
 choices=['lit','class','star','seq','union'] if depth<3 else ['lit','class']
 k=random.choice(choices)
 if k=='lit':
  c=random.choice(literals); return ('lit',c)
 if k=='class':
  items=[]
  for _ in range(random.randint(1,3)):
   if random.random()<0.5:
    lo=random.choice('abc012'); hi=chr(random.randint(ord(lo),ord('z'))) if lo.isalpha() else chr(random.randint(ord(lo),ord('9')))
    if lo=='0': hi=random.choice('0123456789')
    elif lo=='1': hi=random.choice('123456789')
    elif lo=='2': hi=random.choice('23456789')
    items.append(('range',lo,hi)); continue
   c=random.choice('abc-]\\[]*|().')
   items.append(('single',c))
  return ('class',items)
 if k=='star': return ('star',gen(depth+1))
 if k=='seq': return ('seq',[gen(depth+1) for _ in range(random.randint(0,3))])
 return ('union',[gen(depth+1) for _ in range(random.randint(2,4))])
def ser(node):
 k=node[0]
 if k=='lit':return enc_lit(node[1])
 if k=='class':
  s='['
  for item in node[1]:
   if item[0]=='single':s+=enc_class_lit(item[1])
   else:s+=enc_class_lit(item[1])+'-'+enc_class_lit(item[2])
  return s+']'
 if k=='star':return '('+ser(node[1])+')*'
 if k=='seq':return ''.join(ser(x) for x in node[1])
 if k=='union':return '('+'|'.join(ser(x) for x in node[1])+')'
def py(node):
 k=node[0]
 if k=='lit':return re.escape(node[1])
 if k=='class':
  s='['
  for item in node[1]:
   if item[0]=='single':s+=re.escape(item[1])
   else:s+=re.escape(item[1])+'-'+re.escape(item[2])
  return s+']'
 if k=='star':return '(?:'+py(node[1])+')*'
 if k=='seq':return ''.join(py(x) for x in node[1])
 if k=='union':return '(?:'+'|'.join(py(x) for x in node[1])+')'
for trial in range(5000):
 ast=gen();pat=ser(ast);pyre=py(ast)
 try:p=Pattern(pat);r=re.compile(pyre)
 except Exception as e:
  print('compile err',pat,pyre,e);break
 for _ in range(20):
  s=''.join(random.choice('abc012-.]\\[]*|().') for _ in range(random.randint(0,8)))
  if p.fullmatch(s)!=bool(r.fullmatch(s)):
   print('MISMATCH',pat,pyre,repr(s),p.fullmatch(s),bool(r.fullmatch(s)));raise SystemExit
else:print('all ok')
